// LINE イベント解析
const body = $input.first().json;

// イベント取得
const events = body.body?.events || body.events || [];
if (!events.length) {
  return [{ json: { skip: true, reason: 'No events' } }];
}

const event = events[0];

// テキストメッセージ以外はスキップ
if (event.type !== 'message' || event.message?.type !== 'text') {
  return [{ json: { skip: true, reason: 'Not text message' } }];
}

return [{
  json: {
    skip: false,
    replyToken: event.replyToken,
    lineUserId: event.source?.userId || 'unknown',
    userMessage: event.message.text
  }
}];

// 過去の会話履歴をAnthropic messages形式に変換
const history = $('会話履歴取得').all().map(item => item.json);
const userMessage = $('LINE Event 解析').first().json.userMessage;

// 履歴は DESC で取得しているので reverse
const reversed = history.reverse();

// messages 配列を構築（最後の1件=今のメッセージは除外）
const messages = [];
for (let i = 0; i < reversed.length - 1; i++) {
  messages.push({
    role: reversed[i].role,
    content: reversed[i].message
  });
}
// 今のメッセージを追加
messages.push({ role: 'user', content: userMessage });

return [{ json: { messages } }];

// Claude APIレスポンスからテキスト抽出
const response = $input.first().json;
let assistantMessage = '';

if (response.content && Array.isArray(response.content)) {
  assistantMessage = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('');
} else if (typeof response.text === 'string') {
  assistantMessage = response.text;
}

// LINEメッセージは5000文字制限
if (assistantMessage.length > 5000) {
  assistantMessage = assistantMessage.substring(0, 4997) + '...';
}

return [{
  json: {
    assistantMessage: assistantMessage.trim(),
    replyToken: $('LINE Event 解析').first().json.replyToken,
    lineUserId: $('LINE Event 解析').first().json.lineUserId
  }
}];
